TOKEN_SECRET=hmac.new(b"ZAKO_TEST_TOKEN",BOT_TOKEN.encode(),hashlib.sha256).digest()

def validate_telegram_init_data(init_data:str):
    if not init_data:return None
    try:
        p=urllib.parse.parse_qs(init_data,keep_blank_values=True,strict_parsing=True);rh=p.get("hash",[None])[0]
        if not rh:return None
        check="\n".join(f"{k}={p[k][0]}" for k in sorted(p) if k!="hash" and p[k])
        sk=hmac.new(b"WebAppData",BOT_TOKEN.encode(),hashlib.sha256).digest()
        ch=hmac.new(sk,check.encode(),hashlib.sha256).hexdigest()
        if not hmac.compare_digest(ch,rh):return None
        u=json.loads(p.get("user",[None])[0] or "null")
        return u if isinstance(u,dict) and u.get("id") else None
    except (ValueError,TypeError,json.JSONDecodeError):return None

def telegram_user_from_request(request:Request,body=None):
    data=request.headers.get("X-Telegram-Init-Data")
    if not data and body:data=body.get("initData","")
    return validate_telegram_init_data(data or "")

def create_test_token(uid,typ,qids):
    payload={"uid":uid,"type":typ,"q":qids,"exp":int(datetime.now(timezone.utc).timestamp())+1800,"nonce":secrets.token_hex(8)}
    b64=urllib.parse.quote_from_bytes(json.dumps(payload,separators=(",",":")).encode())
    sig=hmac.new(TOKEN_SECRET,b64.encode(),hashlib.sha256).hexdigest()
    return f"{b64}.{sig}"

def verify_test_token(token,uid):
    try:
        b64,sig=token.rsplit(".",1);exp=hmac.new(TOKEN_SECRET,b64.encode(),hashlib.sha256).hexdigest()
        if not hmac.compare_digest(exp,sig):return None
        p=json.loads(urllib.parse.unquote_to_bytes(b64).decode())
        if int(p.get("uid"))!=int(uid) or int(p.get("exp",0))<int(datetime.now(timezone.utc).timestamp()):return None
        qids=p.get("q");typ=p.get("type")
        if not isinstance(qids,list) or len(qids)!=10 or len(set(qids))!=10 or typ not in QUESTION_SETS:return None
        if any(q not in QUESTION_BY_ID or QUESTION_BY_ID[q]["type"]!=typ for q in qids):return None
        return p
    except (ValueError,TypeError,json.JSONDecodeError,UnicodeDecodeError):return None

async def init_db():
    global db_pool
    db_pool=await asyncpg.create_pool(DATABASE_URL,min_size=1,max_size=5,command_timeout=10)
    async with db_pool.acquire() as c:
        await c.execute("""CREATE TABLE IF NOT EXISTS users(telegram_id BIGINT PRIMARY KEY,username TEXT,first_name TEXT,best_score INTEGER NOT NULL DEFAULT 0,tests_taken INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())""")
        await c.execute("""CREATE TABLE IF NOT EXISTS test_results(id BIGSERIAL PRIMARY KEY,telegram_id BIGINT NOT NULL REFERENCES users(telegram_id) ON DELETE CASCADE,test_type TEXT NOT NULL DEFAULT 'iq',score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100),correct_answers INTEGER NOT NULL CHECK(correct_answers>=0),total_questions INTEGER NOT NULL CHECK(total_questions>0),total_time_seconds REAL NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())""")
        await c.execute("ALTER TABLE test_results ADD COLUMN IF NOT EXISTS test_type TEXT NOT NULL DEFAULT 'iq'")
        await c.execute("ALTER TABLE test_results ADD COLUMN IF NOT EXISTS total_time_seconds REAL NOT NULL DEFAULT 0")
        await c.execute("CREATE INDEX IF NOT EXISTS idx_test_results_user ON test_results(telegram_id,created_at DESC)")
        await c.execute("CREATE INDEX IF NOT EXISTS idx_users_best_score ON users(best_score DESC,tests_taken ASC,updated_at ASC)")

async def close_db():
    global db_pool
    if db_pool is not None:await db_pool.close();db_pool=None

async def upsert_user(user):
    tid=int(user["id"])
    async with db_pool.acquire() as c:
        await c.execute("""INSERT INTO users(telegram_id,username,first_name) VALUES($1,$2,$3) ON CONFLICT(telegram_id) DO UPDATE SET username=EXCLUDED.username,first_name=EXCLUDED.first_name,updated_at=NOW()""",tid,user.get("username"),user.get("first_name",""))
    return tid

@dp.message(CommandStart())
async def start_handler(message:types.Message):
    kb=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🚀 ZAKO'NI OCHISH",web_app=WebAppInfo(url=PUBLIC_URL))]])
    await message.answer("🧠 <b>ZAKO</b>\n\nO'zingni sinab ko'r.\nQanchalik ZAKOsan?",reply_markup=kb,parse_mode="HTML")

@app.get("/",response_class=HTMLResponse)
async def home():return HTMLResponse(HTML)

@app.get("/health")
async def health():return {"status":"ok","service":"zako-bot","database":db_pool is not None,"question_counts":{k:len(v) for k,v in QUESTION_BANKS.items()}}

@app.post(WEBHOOK_PATH)
async def telegram_webhook(request:Request):
    data=await request.json();update=types.Update.model_validate(data,context={"bot":bot});await dp.feed_update(bot,update);return {"ok":True}

@app.post("/api/test/start")
async def start_test(request:Request):
    body=await request.json();user=telegram_user_from_request(request,body)
    if not user:return {"ok":False,"error":"Telegram userni tasdiqlab bo'lmadi."}
    typ=body.get("testType","iq")
    if typ not in QUESTION_SETS:return {"ok":False,"error":"Test turi noto'g'ri."}
    tid=await upsert_user(user);pool=QUESTION_BANKS[typ]
    selected=random.sample(pool,10)
    qids=[f"{typ}_{pool.index(x)+1}" for x in selected]
    return {"ok":True,"testToken":create_test_token(tid,typ,qids),"testType":typ,"testName":QUESTION_SETS[typ],
            "questions":[{"id":q,"q":QUESTION_BY_ID[q]["q"],"a":QUESTION_BY_ID[q]["a"]} for q in qids]}

@app.post("/api/test/submit")
async def submit_test(request:Request):
    body=await request.json();user=telegram_user_from_request(request,body)
    if not user:return {"ok":False,"error":"Telegram userni tasdiqlab bo'lmadi."}
    tid=int(user["id"]);tok=verify_test_token(body.get("testToken",""),tid)
    if not tok:return {"ok":False,"error":"Test sessiyasi yaroqsiz yoki muddati o'tgan."}
    answers=body.get("answers")
    if not isinstance(answers,list) or len(answers)!=10:return {"ok":False,"error":"Test to'liq yakunlanmagan."}
    expected=tok["q"];received=[];correct=0;total=0.0
    for pos,item in enumerate(answers):
        if not isinstance(item,dict):return {"ok":False,"error":"Javob formati noto'g'ri."}
        try:qid=str(item["questionId"]);ai=int(item["answerIndex"]);ts=float(item["timeSeconds"])
        except (KeyError,TypeError,ValueError):return {"ok":False,"error":"Javob ma'lumotlari noto'g'ri."}
        if qid!=expected[pos] or qid in received:return {"ok":False,"error":"Test javoblari noto'g'ri yoki takrorlangan."}
        if not -1<=ai<4 or not 0<=ts<=15.5:return {"ok":False,"error":"Javob qiymati noto'g'ri."}
        received.append(qid);total+=min(15,max(0,ts))
        if ai==QUESTION_BY_ID[qid]["correct"]:correct+=1
    score=round(max(0,min(100,(correct/10)*70+max(0,30-(total/10/15)*30))))
    async with db_pool.acquire() as c:
        await c.execute("""INSERT INTO users(telegram_id,username,first_name) VALUES($1,$2,$3) ON CONFLICT(telegram_id) DO UPDATE SET username=EXCLUDED.username,first_name=EXCLUDED.first_name,updated_at=NOW()""",tid,user.get("username"),user.get("first_name",""))
        await c.execute("INSERT INTO test_results(telegram_id,test_type,score,correct_answers,total_questions,total_time_seconds) VALUES($1,$2,$3,$4,10,$5)",tid,tok["type"],score,correct,round(total,2))
        await c.execute("UPDATE users SET best_score=GREATEST(best_score,$2),tests_taken=tests_taken+1,updated_at=NOW() WHERE telegram_id=$1",tid,score)
    return {"ok":True,"score":score,"correctAnswers":correct,"totalQuestions":10,"testType":tok["type"]}

@app.get("/api/me")
async def get_me(request:Request):
    user=telegram_user_from_request(request)
    if not user:return {"ok":False,"error":"Telegram userni tasdiqlab bo'lmadi."}
    tid=await upsert_user(user)
    async with db_pool.acquire() as c:row=await c.fetchrow("SELECT telegram_id,username,first_name,best_score,tests_taken FROM users WHERE telegram_id=$1",tid)
    return {"ok":True,"user":{"id":row["telegram_id"] if row else tid,"username":row["username"] if row else user.get("username"),"first_name":row["first_name"] if row else user.get("first_name","")},"best_score":row["best_score"] if row else 0,"tests_taken":row["tests_taken"] if row else 0}

@app.get("/api/ranking")
async def ranking():
    async with db_pool.acquire() as c:rows=await c.fetch("SELECT username,first_name,best_score,tests_taken FROM users WHERE tests_taken>0 ORDER BY best_score DESC,tests_taken ASC,updated_at ASC LIMIT 100")
    return {"ok":True,"users":[{"username":r["username"],"first_name":r["first_name"],"best_score":r["best_score"],"tests_taken":r["tests_taken"]} for r in rows]}

@asynccontextmanager
async def lifespan(app_instance:FastAPI):
    await init_db();await bot.set_webhook(url=WEBHOOK_URL,drop_pending_updates=True)
    try:yield
    finally:
        try:await bot.delete_webhook()
        finally:await bot.session.close();await close_db()
app.router.lifespan_context=lifespan
